import org.junit.Test;
import static org.junit.Assert.*;

public class Element_nextElementSibling_TriageGen2Test {









    @Test(expected = NullPointerException.class)
    public void testNextElementSibling_ThrowsExceptionWhenNoParent() {
        // Creating an element not attached to a document/parent
        Element orphan = new Element(org.jsoup.parser.Tag.valueOf("div"), "");
        // In jsoup, parent() returns null if not attached. 
        // The method calls parent().children(). If parent() is null, it throws NPE.
        orphan.nextElementSibling();
    }
}
